    key: str = "release_id",
    software_list: List[dict] = None,
    states: List[str] = ["prestaged"],
) -> bool:
    """Check if version is valid for prestage"""
    if not software_list:
        return False

    for software in software_list:
        if software.get(key) == version and software.get("state") in states:
            return True
    return False
